    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int intervalsLen = Integer.parseInt(lines.get(pos++).trim());
        int[][] intervals = new int[intervalsLen][2];
        for (int i = 0; i < intervalsLen; i++) {
            StringTokenizer st = new StringTokenizer(lines.get(pos++));
            intervals[i][0] = Integer.parseInt(st.nextToken());
            intervals[i][1] = Integer.parseInt(st.nextToken());
        }
        int newIntervalLen = Integer.parseInt(lines.get(pos++).trim());
        int[] newInterval = new int[newIntervalLen];
        if (newIntervalLen > 0) {
            StringTokenizer st = new StringTokenizer(lines.get(pos));
            for (int i = 0; i < newIntervalLen; i++) newInterval[i] = Integer.parseInt(st.nextToken());
        }
        pos++;
        int[][] result = solve(intervals, newInterval);
        for (int[] row : result) {
            System.out.println(row[0] + " " + row[1]);
        }
    }
}

